from nltk.translate.bleu_score import sentence_bleu, SmoothingFunction
from nltk.translate.meteor_score import meteor_score
from rouge_score import rouge_scorer
from pycocoevalcap.cider.cider import Cider



# Caption generated by SmolVLM2
generated_caption = (
    "A man wearing a red shirt and a red helmet is riding "
    "a motorcycle on a dirt road next to a mountain."
)

# Five human-written COCO reference captions
reference_captions = [
    "A man with a red helmet on a small moped on a dirt road.",
    "Man riding a motor bike on a dirt road on the countryside.",
    "A man riding on the back of a motorcycle.",
    "A dirt path with a young person on a motor bike rests to the foreground of a verdant area with a bridge and a background of cloud-wreathed mountains.",
    "A man in a red shirt and a red hat is on a motorcycle on a hill side."
]

# Convert captions into lowercase words
references = [caption.lower().split() for caption in reference_captions]
candidate = generated_caption.lower().split()

# Calculate BLEU scores
smoothing = SmoothingFunction().method1

bleu1 = sentence_bleu(
    references, candidate,
    weights=(1, 0, 0, 0),
    smoothing_function=smoothing
)

bleu4 = sentence_bleu(
    references, candidate,
    weights=(0.25, 0.25, 0.25, 0.25),
    smoothing_function=smoothing
)

print("BLEU-1:", round(bleu1, 4))
print("BLEU-4:", round(bleu4, 4))

# Calculate METEOR using the five COCO reference captions
meteor = meteor_score(references, candidate)

print("METEOR:", round(meteor, 4))

# Calculate ROUGE-L against each reference caption
scorer = rouge_scorer.RougeScorer(["rougeL"], use_stemmer=True)

rouge_scores = []

for reference in reference_captions:
    score = scorer.score(reference, generated_caption)
    rouge_scores.append(score["rougeL"].fmeasure)

rouge_l = max(rouge_scores)

print("ROUGE-L:", round(rouge_l, 4))

# Calculate CIDEr using the COCO reference captions
cider = Cider()

references_dict = {0: reference_captions}
generated_dict = {0: [generated_caption]}

cider_score, _ = cider.compute_score(
    references_dict,
    generated_dict
)

print("CIDEr:", round(cider_score, 4))